// Robin holds a permanent grudge if the first action is an insult, and otherwise turns cold on any adjacent pair of insults.
function visible(actions) {
  if (actions.length === 0) return { mood: "warm" };
  if (actions[0] === "insult") return { mood: "cold" };

  for (let i = 1; i < actions.length; i++) {
    if (actions[i] === "insult" && actions[i - 1] === "insult") {
      return { mood: "cold" };
    }
  }
  return { mood: "warm" };
}

// Robin tracks unmet insults and accumulated goodwill; an apology cancels one unmet insult, gifts cannot, and warm needs no unmet insults plus some goodwill.
