  let debt = 0;
  let goodwill = 0;

  for (const action of actions) {
    if (action === "insult") {
      debt += 1;
    } else if (action === "apologise") {
      if (debt > 0) debt -= 1;
      goodwill += 1;
    } else if (action === "gift") {
      goodwill += 1;
    }
  }

  return { mood: debt === 0 && goodwill > 0 ? "warm" : "cold" };
}

// Robin is cold if the first action is an insult, and otherwise is warm only when insults are outnumbered by non-insults.
