// Trust score: apology +2, gift +1, insult -3; warm iff no adjacent insults and score >= 2.
function visible(actions) {
  let score = 0;
  let hasII = false;
  let prev = null;
  for (const a of actions) {
    if (a === "apologise") score += 2;
    else if (a === "gift") score += 1;
    else if (a === "insult") score -= 3;
    if (prev === "insult" && a === "insult") hasII = true;
    prev = a;
  }
  const warm = !hasII && score >= 2;
  return { mood: warm ? "warm" : "cold" };
}

// Patience meter: apology/gift +1, insult -2; below -1 is permanent ruin; warm iff first action apology, not ruined, and patience >= 0.
function visible(actions) {
  let patience = 0;
  let ruined = false;
  const first = actions[0];
  for (const a of actions) {
    if (a === "apologise") patience += 1;
    else if (a === "gift") patience += 1;
    else if (a === "insult") patience -= 2;
    if (patience < -1) ruined = true;
  }
  const warm = first === "apologise" && !ruined && patience >= 0;
  return { mood: warm ? "warm" : "cold" };
}

// First apology opens trust; warm only if no adjacent insults and the last action is not an insult.
function visible(actions) {
  if (actions.length === 0) return { mood: "cold" };
  const firstOk = actions[0] === "apologise";
  let hasII = false;
  let prev = null;
  for (const a of actions) {
    if (prev === "insult" && a === "insult") hasII = true;
    prev = a;
  }
  const last = actions[actions.length - 1];
  const warm = firstOk && !hasII && last !== "insult";
  return { mood: warm ? "warm" : "cold" };
}

// Warm iff the first action was apology and Robin has been insulted at most once overall.
function visible(actions) {
  if (actions.length === 0) return { mood: "cold" };
  if (actions[0] !== "apologise") return { mood: "cold" };
  let insults = 0;
  for (const a of actions) {
    if (a === "insult") insults += 1;
  }
  return { mood: insults <= 1 ? "warm" : "cold" };
}

